    .add(interactions.orbit({ target: "cube" })) // target is a node NAME
    .camera(camera.orbit({ position: [2.8, 1.9, 3.4], target: [0, 0, 0], fov: 40 }))
});

let angle = 0;
app.onFrame((frame) => {
  angle += frame.dt * 0.8; // animate in onFrame, scaled by frame.dt
